  let books: Books = {};
  const run = (command: Command, id: string): Outcome => {
    if (typeof id !== 'string') return { ok: false, reason: 'invalid-book-id' };
    const d = decide(books, command, id);
    if (!d.ok) return { ok: false, reason: d.reason };
    books = d.books;
    return { ok: true };
  };
  const host: Host = {
    add: async (id) => run('add', id),
