    book: async (id): Promise<BookView | null> => {
      if (typeof id !== 'string' || !Object.prototype.hasOwnProperty.call(books, id)) return null;
      const b = books[id];
      return { status: b.status, loans: b.loans };
    },
  };
  return host;
};

export default createHost;
