// Replays the implementation against the polygraph spec: every reachable
// command sequence up to depth 5 over two ids (plus random long walks) must
// give the same outcome and the same book views in both.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import createHost from '../src/host.impl.ts';

const spec = loadSpec(new URL('../spec/loans.spec.cjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const CMDS = [['add', 'ADD'], ['lend', 'LEND'], ['giveBack', 'GIVE_BACK'], ['retire', 'RETIRE']] as const;
const IDS = ['a', 'b'];
const STEPS = CMDS.flatMap(([m, a]) => IDS.map((id) => ({ m, a, id })));

async function replay(seq: typeof STEPS) {
  const h = await createHost();
  spec.init();
  for (const s of seq) {
    const before = JSON.stringify(spec.getState());
    spec.actions[s.a]({ book: s.id });
    const specOk = JSON.stringify(spec.getState()) !== before;
    const out = await h[s.m](s.id);
    assert.equal(out.ok, specOk, `${seq.map((x) => x.m + ':' + x.id).join(' ')}`);
    if (!out.ok) assert.ok(typeof out.reason === 'string' && out.reason.length > 0);
    for (const id of IDS) {
      const want = spec.getState().books[id] ?? null;
      assert.deepEqual(await h.book(id), want);
    }
  }
}

test('impl conforms to spec, exhaustive to depth 4', async () => {
  let frontier: (typeof STEPS)[] = [[]];
  for (let d = 0; d < 4; d++) {
    const nextF: (typeof STEPS)[] = [];
    for (const seq of frontier) for (const s of STEPS) nextF.push([...seq, s]);
    frontier = nextF;
    for (const seq of frontier) await replay(seq);
  }
});

test('impl conforms to spec, random long walks', async () => {
  let seed = 12345;
  const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
  for (let r = 0; r < 300; r++) {
    const seq = Array.from({ length: 40 }, () => STEPS[Math.floor(rnd() * STEPS.length)]);
    await replay(seq);
  }
});

