'use strict';
// SAM v2 strict-profile spec of the book-loans core (src/core.ts).
// State: books — a map id -> { status, loans, renewed }; an absent id is a book never added.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { books: {} };
const MAX_LOANS = 3;
const IDS = ['a', 'b'];
const domain = IDS.map((book) => ({ book }));
const schema = { book: { type: 'string' } };
const intent = () => ({ action: (data = {}) => ({ ...data }), schema, domain });
const has = (books, id) => Object.prototype.hasOwnProperty.call(books, id);

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      books: { type: 'object' },
    },
    actions: {
      ADD: intent(),
      LEND: intent(),
      GIVE_BACK: intent(),
      RETIRE: intent(),
      RENEW: intent(),
    },
    acceptors: {
      ADD: (model) => (p, { reject, next }) => {
        if (has(model.books, p.book)) return reject('book-exists');
        next.books = { ...model.books, [p.book]: { status: 'available', loans: 0, renewed: false } };
      },
      LEND: (model) => (p, { reject, next }) => {
        if (!has(model.books, p.book)) return reject('unknown-book');
        const b = model.books[p.book];
        if (b.status === 'retired') return reject('book-retired');
        if (b.status !== 'available') return reject('not-available');
        if (b.loans >= MAX_LOANS) return reject('loan-limit-reached');
        next.books = { ...model.books, [p.book]: { status: 'lent', loans: b.loans + 1, renewed: false } };
      },
      GIVE_BACK: (model) => (p, { reject, next }) => {
        if (!has(model.books, p.book)) return reject('unknown-book');
        const b = model.books[p.book];
        if (b.status === 'retired') return reject('book-retired');
        if (b.status !== 'lent') return reject('not-lent');
        next.books = { ...model.books, [p.book]: { status: 'available', loans: b.loans, renewed: false } };
      },
      RETIRE: (model) => (p, { reject, next }) => {
        if (!has(model.books, p.book)) return reject('unknown-book');
        const b = model.books[p.book];
        if (b.status === 'retired') return reject('book-retired');
        if (b.status !== 'available') return reject('not-available');
        next.books = { ...model.books, [p.book]: { status: 'retired', loans: b.loans, renewed: false } };
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  ADD: (data = {}) => intents.ADD(data),
  LEND: (data = {}) => intents.LEND(data),
  GIVE_BACK: (data = {}) => intents.GIVE_BACK(data),
  RETIRE: (data = {}) => intents.RETIRE(data),
  RENEW: (data = {}) => intents.RENEW(data),
};

module.exports = { instance, init, actions, getState, setState };

