// Rules the brief requires, stated independently of the spec.
const STATUSES = ['available', 'lent', 'retired'];
const books = (s) => (s && s.books) || {};
const get = (s, id) => (Object.prototype.hasOwnProperty.call(books(s), id) ? books(s)[id] : null);
const ids = (...ss) => [...new Set(ss.flatMap((s) => Object.keys(books(s))))];
const same = (x, y) => JSON.stringify(x) === JSON.stringify(y);

export const stateInvariants = [
  { name: 'status-is-legal', pred: (s) => Object.values(books(s)).every((b) => STATUSES.includes(b.status)) },
  { name: 'loans-between-0-and-3', pred: (s) => Object.values(books(s)).every((b) => Number.isInteger(b.loans) && b.loans >= 0 && b.loans <= 3) },
  // one borrower at a time: a lent book has been lent at least once (its current loan)
  { name: 'lent-implies-a-loan', pred: (s) => Object.values(books(s)).every((b) => b.status !== 'lent' || b.loans >= 1) },
];

export const transitionInvariants = [
  { name: 'books-never-disappear', pred: (pre, a, d, post) => Object.keys(books(pre)).every((id) => get(post, id) !== null) },
  { name: 'only-target-book-changes', pred: (pre, a, d, post) => ids(pre, post).every((id) => id === d.book || same(get(pre, id), get(post, id))) },
  { name: 'retired-is-final', pred: (pre, a, d, post) => ids(pre).every((id) => get(pre, id).status !== 'retired' || same(get(pre, id), get(post, id))) },
  { name: 'loans-never-decrease', pred: (pre, a, d, post) => ids(pre).every((id) => get(post, id).loans >= get(pre, id).loans) },
  { name: 'loan-count-rises-only-on-lend', pred: (pre, a, d, post) => ids(pre).every((id) => {
      const before = get(pre, id), after = get(post, id);
      if (after.loans === before.loans) return true;
      return a === 'LEND' && before.status === 'available' && after.status === 'lent' && after.loans === before.loans + 1;
    }) },
  { name: 'never-lent-twice-at-once', pred: (pre, a, d, post) => !(a === 'LEND' && get(pre, d.book)?.status === 'lent' && !same(pre, post)) },
  { name: 'retired-never-lent-again', pred: (pre, a, d, post) => !(get(pre, d.book)?.status === 'retired' && get(post, d.book)?.status === 'lent') },
  { name: 'add-creates-fresh-available', pred: (pre, a, d, post) => a !== 'ADD' || get(pre, d.book) !== null || same(get(post, d.book), { status: 'available', loans: 0 }) },
  { name: 'unknown-book-only-added', pred: (pre, a, d, post) => a === 'ADD' || get(pre, d.book) !== null || same(pre, post) },
];

// Every refusal the brief requires must be an observable rejection.
const mustReject = (pre, a, d) => {
  const b = get(pre, d.book);
  if (a === 'ADD') return b !== null;
  if (b === null) return true;
  if (a === 'LEND') return b.status !== 'available' || b.loans >= 3;
  if (a === 'GIVE_BACK') return b.status !== 'lent';
  if (a === 'RETIRE') return b.status !== 'available';
  return false;
};
export const rejectionInvariants = [
  { name: 'refusals-match-brief', pred: (pre, a, d, v) => mustReject(pre, a, d) === !!(v && v.rejected) },
];

