test('renew once per loan, again after a new loan', async () => {
  const h = await createHost();
  refused(await h.renew('a'));
  await h.add('a');
  refused(await h.renew('a'));
  ok(await h.lend('a'));
  ok(await h.renew('a'));
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 1, renewed: true });
  refused(await h.renew('a'));
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 1, renewed: true });
  ok(await h.giveBack('a'));
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 1, renewed: false });
  refused(await h.renew('a'));
  ok(await h.lend('a'));
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 2, renewed: false });
  ok(await h.renew('a'));
  ok(await h.giveBack('a'));
  ok(await h.retire('a'));
  refused(await h.renew('a'));
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 2, renewed: false });
});

