import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const refused = (o: { ok: boolean }) => assert.equal(o.ok, false);
const ok = (o: { ok: boolean }) => assert.deepEqual(o, { ok: true });

test('fresh system has no books; unknown ids are refused', async () => {
  const h = await createHost();
  assert.equal(await h.book('a'), null);
  refused(await h.lend('a'));
  refused(await h.giveBack('a'));
  refused(await h.retire('a'));
  assert.equal(await h.book('a'), null);
});

test('add, duplicate add refused', async () => {
  const h = await createHost();
  ok(await h.add('a'));
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 0, renewed: false });
  const r = await h.add('a');
  refused(r);
  assert.equal(typeof (r as { reason: string }).reason, 'string');
});

test('lend / giveBack cycle and three-loan limit', async () => {
  const h = await createHost();
  await h.add('a');
  refused(await h.giveBack('a'));
  ok(await h.lend('a'));
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 1, renewed: false });
  refused(await h.lend('a'));
  refused(await h.retire('a'));
  ok(await h.giveBack('a'));
  ok(await h.lend('a')); ok(await h.giveBack('a'));
  ok(await h.lend('a')); ok(await h.giveBack('a'));
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3, renewed: false });
  refused(await h.lend('a'));
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3, renewed: false });
  ok(await h.retire('a'));
});

test('retired book accepts nothing', async () => {
  const h = await createHost();
  await h.add('a');
  ok(await h.retire('a'));
  refused(await h.lend('a'));
  refused(await h.giveBack('a'));
  refused(await h.retire('a'));
  refused(await h.add('a'));
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 0, renewed: false });
});

test('systems are independent; books independent', async () => {
  const h1 = await createHost();
  const h2 = await createHost();
  await h1.add('a');
  assert.equal(await h2.book('a'), null);
  await h1.add('b');
  await h1.lend('a');
  assert.deepEqual(await h1.book('b'), { status: 'available', loans: 0, renewed: false });
  // views are snapshots
  const v = await h1.book('b');
  if (v) v.loans = 99;
  assert.deepEqual(await h1.book('b'), { status: 'available', loans: 0, renewed: false });
  assert.equal(await h1.book('__proto__'), null);
  assert.equal(await h1.book('toString'), null);
  ok(await h1.add('__proto__'));
  ok(await h1.lend('__proto__'));
  assert.deepEqual(await h1.book('__proto__'), { status: 'lent', loans: 1, renewed: false });
});

